// lib/core/services/ask_iman_ai_service.dart
//
// Client-side ASK Iman AI.
// Calls the Gemini API directly over HTTPS (no Cloud Functions / no Blaze)
// and grounds Quran + Hadith authenticity checks against live public corpora.
//
// SAFETY: citations are only ever emitted from corpus retrieval results,
// never generated by the model. Unmatched text always gets the honest
// "I cannot verify" answer instead of an invention.

