// ── Model classes ────────────────────────────────────────────────────────────
class AskAICitation {
  final String kind; // 'ayah' | 'hadith'
  final String book;
  final int? surahNumber;
  final String? surahName;
  final String? surahArabic;
  final int? ayahNumber;
  final int? hadithNumber;
  final String arabic;
  final String text; // ayah translation / hadith english text
  final String? grade;

  const AskAICitation({
    required this.kind,
    required this.book,
    this.surahNumber,
    this.surahName,
    this.surahArabic,
    this.ayahNumber,
    this.hadithNumber,
    this.arabic = '',
    this.text = '',
    this.grade,
  });

  factory AskAICitation.fromJson(Map<String, dynamic> j) {
    return AskAICitation(
      kind: j['kind'] as String? ?? 'hadith',
      book: j['book'] as String? ?? '',
      surahNumber: j['surahNumber'] as int?,
      surahName: j['surahName'] as String?,
      surahArabic: j['surahArabic'] as String?,
      ayahNumber: j['ayahNumber'] as int?,
      hadithNumber: j['hadithNumber'] as int?,
      arabic: j['arabic'] as String? ?? '',
      text: j['text'] as String? ?? '',
      grade: j['grade'] as String?,
    );
  }

  Map<String, dynamic> toJson() => {
        'kind': kind,
        'book': book,
        'surahNumber': surahNumber,
        'surahName': surahName,
        'surahArabic': surahArabic,
        'ayahNumber': ayahNumber,
        'hadithNumber': hadithNumber,
        'arabic': arabic,
        'text': text,
        'grade': grade,
      };

  String get shortLabel {
    if (kind == 'ayah') {
      return '$surahName ($surahArabic) $surahNumber:$ayahNumber';
    }
    return hadithNumber != null ? '$book — #$hadithNumber' : book;
  }
}

class AskAIResponse {
  final String verdict; // verified | unverified | refused | answer
  final String type; // quran | hadith | general_qna | out_of_scope
  final String answer;
  final List<AskAICitation> citations;
  final String lang;
  final String? errorCode; // set when the call was blocked before answering

  const AskAIResponse({
    required this.verdict,
    required this.type,
    required this.answer,
    this.citations = const [],
    this.lang = 'en',
    this.errorCode,
  });

  bool get isVerified => verdict == 'verified';
  bool get isBlocked => errorCode != null;

  factory AskAIResponse.fromJson(Map<String, dynamic> j) {
    return AskAIResponse(
      verdict: j['verdict'] as String? ?? 'unverified',
      type: j['type'] as String? ?? 'general_qna',
      answer: j['answer'] as String? ?? '',
      citations: ((j['citations'] as List?) ?? [])
          .whereType<Map>()
          .map((e) => AskAICitation.fromJson(Map<String, dynamic>.from(e)))
          .toList(),
      lang: j['lang'] as String? ?? 'en',
      errorCode: j['errorCode'] as String?,
    );
  }

  Map<String, dynamic> toJson() => {
        'verdict': verdict,
        'type': type,
        'answer': answer,
        'citations': citations.map((c) => c.toJson()).toList(),
        'lang': lang,
        'errorCode': errorCode,
      };
}

// ── Pure matching helpers (ported from functions/ai_tools.js) ───────────────
// Kept dependency-free so they can be unit tested.

final RegExp _diacritics =
    RegExp(r'[\u064B-\u065F\u0610-\u061A\u06D6-\u06DC\u06DF-\u06E8\u06EA-\u06ED\u0640\u0670\u0653-\u0655\u06E0\u06E1\u06E2\u06E3\u06E4\u06E5\u06E6\u06E7\u06E8\u06EC\u06ED]');
final RegExp _alefVariants = RegExp(r'[\u0622\u0623\u0625\u0671]');
final RegExp _nonLetterOrNumber = RegExp(r'[^\p{L}\p{N}\s]', unicode: true);

String _alefFix(String ch) {
  switch (ch) {
    case '\u0622':
    case '\u0623':
    case '\u0625':
    case '\u0671':
      return '\u0627';
    default:
      return ch;
  }
}

String normalizeForMatch(String text) {
  return text
      .replaceAll(_diacritics, '')
      .replaceAllMapped(_alefVariants, (m) => _alefFix(m[0]!))
      .replaceAll('\u0649', '\u064A') // alef maqsura -> ya
      .replaceAll('\u0629', '\u0647') // taa marbuta -> ha
      .replaceAll(_nonLetterOrNumber, ' ')
      .replaceAll(RegExp(r'\s+'), ' ')
      .trim()
      .toLowerCase();
}

List<String> _tokens(String text) =>
    normalizeForMatch(text).split(' ').where((t) => t.isNotEmpty).toList();

double containmentScore(String hayText, String needleText) {
  final th = _tokens(hayText);
  final tn = _tokens(needleText);
  if (th.isEmpty || tn.isEmpty) return 0;
  final sh = th.toSet();
  var hit = 0;
  for (final t in tn) {
    if (sh.contains(t)) hit++;
  }
  return hit / tn.length;
}

double overlapScore(String aText, String bText) {
  final ta = _tokens(aText);
  final tb = _tokens(bText);
  if (ta.isEmpty || tb.isEmpty) return 0;
  final sa = ta.toSet();
  final sb = tb.toSet();
  final inter = sa.where(sb.contains).length;
  return inter / (sa.length < sb.length ? sa.length : sb.length);
}

({double score, double containment, double overlap, double lenFactor})
    rankMatch({required String hayText, required String needleText}) {
  final c = containmentScore(hayText, needleText);
  final o = overlapScore(hayText, needleText);
  final n = normalizeForMatch(needleText);
  final h = normalizeForMatch(hayText);
  final lenFactor = n.length <= h.length
      ? 1.0
      : (n.isEmpty ? 0.0 : (1 - (n.length - h.length) / n.length).clamp(0.0, 1.0));
  final score = (c > o ? c : o) * lenFactor;
  return (score: score, containment: c, overlap: o, lenFactor: lenFactor);
}

bool isArabicScript(String text) => RegExp(r'[\u0600-\u06FF]').hasMatch(text);

class CorpusMatch {
  final dynamic item;
  final double score;
  final double containment;
  final double overlap;
  final double lenFactor;
  CorpusMatch(this.item, this.score, this.containment, this.overlap, this.lenFactor);
}

List<CorpusMatch> findMatches(
  List<dynamic> corpusItems, {
  required String Function(dynamic) textOf,
  required String needleText,
  required double minScore,
  int limit = 5,
}) {
  final out = <CorpusMatch>[];
  for (final item in corpusItems) {
    final r = rankMatch(hayText: textOf(item), needleText: needleText);
    if (r.score >= minScore) {
      out.add(CorpusMatch(item, r.score, r.containment, r.overlap, r.lenFactor));
    }
  }
  out.sort((a, b) => b.score.compareTo(a.score));
  return out.take(limit).toList();
}

/// A citation-worthy verdict requires the top hit to clear the strict score
/// AND containment bars AND dominate the runner-up by `gap`. Ties (e.g. a
/// common fragment appearing in many ayahs/hadiths) are deliberately refused
/// instead of guessing — guaranteeing the cited source is not out of context.
({bool ok, CorpusMatch? best}) strictAccept(
  List<CorpusMatch> hits, {
  required double strictScore,
  required double strictContainment,
  required double gap,
}) {
  if (hits.isEmpty) return (ok: false, best: null);
  final top = hits.first;
  final second = hits.length > 1 ? hits[1] : null;
  final ok = top.score >= strictScore &&
      top.containment >= strictContainment &&
      (second == null || (top.score - second.score) >= gap);
  return (ok: ok, best: ok ? top : null);
}

// ── Source-claim parsing ────────────────────────────────────────────────────
// When the user pins a location ("2:255", "surah al-baqarah verse 255",
// "sahih muslim hadith 345", "bukhari 1234") the quote is verified ONLY
// against that exact spot. A mismatch means "this is not in my knowledge" —
// we never cross-reference a different location than the one the user named.

/// Arabic-Indic digits (٠-٩) → ASCII for claim numbers.
String _arabicDigit(int cp) => '${cp - 0x0660}';

Map<String, int> surahNameIndex(Iterable items) {
  final idx = <String, int>{};
  for (final i in items) {
    final s = (i as Map)['surah'] as Map?;
    if (s == null) continue;
    final n = s['number'] as int?;
    if (n == null) continue;
    for (final name in [s['englishName'], s['meaning'], s['name']]) {
      if (name is String && name.isNotEmpty) {
        idx[normalizeForMatch(name).trim()] = n;
      }
    }
  }
  return idx;
}

int? _nameMatch(String raw, bool fromStart, Map<String, int> idx) {
  final p = normalizeForMatch(raw).trim();
  var bestLen = 0;
  int? bestNum;
  idx.forEach((k, n) {
    if (k.isEmpty || k.length <= bestLen) return;
    final ok = fromStart ? p.startsWith(k) : p.endsWith(k);
    if (ok) {
      bestLen = k.length;
      bestNum = n;
    }
  });
  return bestNum;
}

/// Extracts a pinned Quran location (surah, verse) from the message, or null.
(int, int)? parseQuranClaim(String input, Map<String, int> surahIndex) {
  final t =
      input.replaceAllMapped(RegExp(r'[٠-٩]'), (m) => _arabicDigit(m[0]!.codeUnitAt(0)));
  final lower = t.toLowerCase();

  // "2:255", "2/255", "2-255"
  final col = RegExp(r'(\d{1,2})\s*[:/-]\s*(\d{1,3})').firstMatch(lower);
  if (col != null) {
    final s = int.tryParse(col.group(1)!);
    final v = int.tryParse(col.group(2)!);
    if (s != null && v != null && s >= 1 && s <= 114 && v >= 1) return (s, v);
  }

  // "surah 2", "surah 18 ayah 10" …
  final sx = RegExp(r'(?:surah|sura|surat|chapter|سوره)\s+(\d{1,2})(?!\d)')
      .firstMatch(lower);
  if (sx != null) {
    final s = int.tryParse(sx.group(1)!);
    if (s == null || s < 1 || s > 114) return null;
    final rest = lower.substring(sx.end);
    final vx = RegExp(r'\d{1,4}').firstMatch(rest);
    final v = vx != null ? int.tryParse(vx.group(0)!) : null;
    if (v != null && v >= 1) return (s, v);
    return null;
  }

  // name forms: "al-baqarah 255", "ayah 255 of surah al baqarah"
  for (final m in RegExp(r'(\d{1,3})').allMatches(lower)) {
    final v = int.tryParse(m.group(1)!);
    if (v == null || v < 1) continue;
    final before = lower.substring(0, m.start);
    final end = m.end + 60 < lower.length ? m.end + 60 : lower.length;
    final after = lower
        .substring(m.end, end)
        .replaceFirst(
            RegExp(r'^(?:\s*(?:of|from|in|is|being)\s+)?(?:surah|sura|surat|سورة)\s*'),
            '');
    final sNo = _nameMatch(before, false, surahIndex) ??
        _nameMatch(after, true, surahIndex);
    if (sNo != null) return (sNo, v);
  }
  return null;
}

/// Extracts a pinned hadith reference (book slug, hadith number?) or null.
(String, int?)? parseHadithClaim(String input) {
  final lower = input.toLowerCase().replaceAll('-', ' ');
  for (final bk in hadithBooks) {
    final slug = bk['slug']!;
    final m = RegExp('${RegExp.escape(slug)}[^\\d]{0,30}?(\\d{1,5})')
        .firstMatch(lower);
    if (m != null) {
      return (slug, int.tryParse(m.group(1)!));
    }
  }
  return null;
}

